declare copy-namespaces preserve, inherit; 
declare namespace myco="http://www.example.com/myco"; 
declare namespace hisco="http://www.example.com/hisco"; 
let $myemps := <myco:employees salaried="false"> <myco:employee id='100'> <myco:name>Samuel</myco:name> </myco:employee> </myco:employees> 
let $newemps := copy $e := $myemps 
                modify replace node $e/@salaried with attribute hisco:salaried {"true"} 
                return $e 
return namespace-uri-for-prefix("hisco", $newemps/myco:employee[1])

declare copy-namespaces preserve, no-inherit; 
declare namespace myco="http://www.example.com/myco"; 
declare namespace hisco="http://www.example.com/hisco"; 
let $myemps := <myco:employees salaried="false"> <myco:employee id='100'> <myco:name>Samuel</myco:name> </myco:employee> </myco:employees> 
let $newemps := copy $e := $myemps 
                modify replace node $e/@salaried with attribute hisco:salaried {"true"} 
                return $e 
return namespace-uri-for-prefix("hisco", $newemps/myco:employee[1])

copy $c := <a><b att0="0"/><c/></a>
modify replace node $c/b/@att0 with attribute att1 { '1' }
return $c

copy $c := <n><a/></n>
modify (
  insert node <b/> before $c/a,
  replace node $c/a with element last { }
)
return $c

copy $c := <_>a</_>
modify replace node $c/text() with $c || 'b'
return data($c)

copy $c := document { <a/> }
modify replace node $c with <b/>
return $c

copy $c := <a><b/></a>
modify replace node $c/b with attribute x { }
return $c

copy $c := <a x=""/>
modify (
  replace node $c/@x with attribute y { },
  replace node $c/@x with attribute z { }
)
return $c

copy $c := <a x="" y=""/>
modify replace node $c/@x with attribute y { }
return $c

copy $c := <a><b/></a>
modify replace node $c/b with document { <x/>, <y/> }
return $c

copy $c := <a x="1"/>
modify replace node $c/@x with attribute x { 2 }
return $c

copy $c := document { <a/> }
modify replace node $c/a with <b/>
return $c

copy $c := document { <a/> }
modify replace node $c/a with ()
return count($c/node())

copy $c := document { <a/> }
modify replace node $c/a with 'x'
return ($c/node() instance of text(), string($c))

copy $c := <a>x<b/>y</a>
modify replace node $c/b with ''
return (count($c/text()), string($c))

copy $c := <a><b/></a>
modify replace node $c/b with <b xmlns="u"/>
return namespace-uri($c/*)
